package course.demo; import com.vaadin.flow.component.grid.*; import com.vaadin.flow.component.orderedlayout.*; import com.vaadin.flow.router.*; @Route("") public class MainView extends VerticalLayout { public MainView(ProductService service){var grid=new Grid<ProductService.ProductDto>(ProductService.ProductDto.class,false);grid.addColumn(ProductService.ProductDto::id).setHeader("ID");grid.addColumn(ProductService.ProductDto::name).setHeader("Название");grid.setItems(service.findAll());add(grid);} }
